IF OBJECT_ID('dbo.users','U') IS NULL CREATE TABLE dbo.users (id INT IDENTITY(1,1) PRIMARY KEY, role NVARCHAR(20) NOT NULL CHECK (role IN ('admin','invigilator')), email NVARCHAR(120) NOT NULL UNIQUE, name NVARCHAR(120) NOT NULL, password_hash NVARCHAR(300) NOT NULL);
IF OBJECT_ID('dbo.students','U') IS NULL CREATE TABLE dbo.students (id INT IDENTITY(1,1) PRIMARY KEY, roll NVARCHAR(30) NOT NULL UNIQUE, name NVARCHAR(120) NOT NULL, dept NVARCHAR(30) NOT NULL, password_hash NVARCHAR(300) NOT NULL);
IF OBJECT_ID('dbo.rooms','U') IS NULL CREATE TABLE dbo.rooms (id INT IDENTITY(1,1) PRIMARY KEY, name NVARCHAR(80) NOT NULL UNIQUE, row_count INT NOT NULL CHECK (row_count BETWEEN 1 AND 20), col_count INT NOT NULL CHECK (col_count BETWEEN 1 AND 20));
IF OBJECT_ID('dbo.exams','U') IS NULL CREATE TABLE dbo.exams (id INT IDENTITY(1,1) PRIMARY KEY, code NVARCHAR(30) NOT NULL UNIQUE, title NVARCHAR(160) NOT NULL, exam_date VARCHAR(10) NOT NULL, start_time VARCHAR(5) NOT NULL, end_time VARCHAR(5) NOT NULL);
IF OBJECT_ID('dbo.enrollments','U') IS NULL CREATE TABLE dbo.enrollments (exam_id INT NOT NULL REFERENCES dbo.exams(id), student_id INT NOT NULL REFERENCES dbo.students(id), PRIMARY KEY (exam_id, student_id));
IF OBJECT_ID('dbo.allocations','U') IS NULL CREATE TABLE dbo.allocations (id INT IDENTITY(1,1) PRIMARY KEY, exam_id INT NOT NULL REFERENCES dbo.exams(id), student_id INT NOT NULL REFERENCES dbo.students(id), room_id INT NOT NULL REFERENCES dbo.rooms(id), seat_no INT NOT NULL, code NVARCHAR(40) NOT NULL UNIQUE, UNIQUE (exam_id, student_id), UNIQUE (exam_id, room_id, seat_no));
IF OBJECT_ID('dbo.attendance','U') IS NULL CREATE TABLE dbo.attendance (id INT IDENTITY(1,1) PRIMARY KEY, allocation_id INT NOT NULL UNIQUE REFERENCES dbo.allocations(id), marked_by NVARCHAR(120) NOT NULL, marked_at VARCHAR(30) NOT NULL);
IF OBJECT_ID('dbo.audit_logs','U') IS NULL CREATE TABLE dbo.audit_logs (id INT IDENTITY(1,1) PRIMARY KEY, at VARCHAR(30) NOT NULL, actor NVARCHAR(120) NOT NULL, action NVARCHAR(240) NOT NULL)
